<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\HasOne;
use Illuminate\Support\Facades\Storage;

/** code is generated by GuestService and is not mass assignable. */
class Guest extends Model
{
    protected $fillable = ['name', 'phone', 'group_name', 'table_number'];

    protected function casts(): array
    {
        return [
            'opened_at' => 'datetime',
            'shared_at' => 'datetime',
            'checked_in_at' => 'datetime',
            'checked_in_pax' => 'integer',
            'is_walk_in' => 'boolean',
            'souvenir_at' => 'datetime',
        ];
    }

    public function invitation(): BelongsTo
    {
        return $this->belongsTo(Invitation::class);
    }

    public function selfieUrl(): ?string
    {
        return $this->selfie_path ? Storage::disk('public')->url($this->selfie_path) : null;
    }

    public function gifts(): HasMany
    {
        return $this->hasMany(EventGift::class);
    }

    public function wishes(): HasMany
    {
        return $this->hasMany(Wish::class);
    }

    /** Latest RSVP answer from this guest's personal link. */
    public function rsvp(): HasOne
    {
        return $this->hasOne(Wish::class)->whereNotNull('attendance')->latestOfMany();
    }

    /** belum | dibagikan | dibuka | rsvp */
    public function statusKey(): string
    {
        return match (true) {
            $this->relationLoaded('rsvp') && $this->rsvp !== null => 'rsvp',
            $this->opened_at !== null => 'dibuka',
            $this->shared_at !== null => 'dibagikan',
            default => 'belum',
        };
    }
}
